def get_unique_backup_dir():
    timestamp = time.strftime('%Y%m%d%H%M%S', time.gmtime())
    return os.path.join(BACKUP_DIR, f'backup_{timestamp}')

def task_func(directory):
    """
    Create a backup of a directory and clean the directory afterwards.
    Parameters:
    - directory (str): The directory path to be backed up and cleaned.
    Returns:
    tuple: A tuple containing:
        - str: The backup directory path.
        - list: A list of any errors encountered during the operation (empty list if no errors).
    """
    if not os.path.isdir(directory):
        return None, ['Directory does not exist: ' + directory]
    backup_dir = get_unique_backup_dir()
    try:
        os.makedirs(backup_dir, exist_ok=True)
    except OSError as e:
        return None, [f'Failed to create backup directory: {e}']
    errors = []
    try:
        for item in os.listdir(directory):
            src_item = os.path.join(directory, item)
            dst_item = os.path.join(backup_dir, item)
            if os.path.isdir(src_item):
                shutil.copytree(src_item, dst_item)
            else:
                shutil.copy2(src_item, dst_item)
    except Exception as e:
        errors.append(f'Failed to copy files to backup directory: {e}')
    try:
        for item in os.listdir(directory):
            item_path = os.path.join(directory, item)
            if os.path.isfile(item_path):
                os.remove(item_path)
            elif os.path.isdir(item_path):
                shutil.rmtree(item_path)
    except Exception as e:
        errors.append(f'Failed to clean directory: {e}')
    return backup_dir, errors
